    public Story() {}

    public Story(String title, int id, boolean loaded, boolean clicked) {
        this.title = title;
        this.id = id;
        this.loaded = loaded;
        this.clicked = clicked;
    }

    public void update(String by, int id, int score, int time, String title) {
        this.by = by;
        this.id = id;
        this.score = score;
        this.time = time;
        this.title = title;
    }

