    public static int getBookmarksIndex(Resources res) {
        String[] sortingOptions = res.getStringArray(R.array.sorting_options);

        for (int i = sortingOptions.length - 1; i >= 0; i--) {
            if (sortingOptions[i].equals("Bookmarks")) {
                return i;
