    if (story == null) {
        return false;
    }

    if (filterWords != null && !TextUtils.isEmpty(story.title)) {
        String title = story.title.toLowerCase();
        for (String phrase : filterWords) {
            if (!TextUtils.isEmpty(phrase) && title.contains(phrase.toLowerCase())) {
                return true;
