import java.util.*;

public class FilterCheck {
    static class Story { String title, url; Story(){} Story(String t,String u){title=t;url=u;} }

    static List<String> filterWords, filterDomains;

    static boolean isEmpty(CharSequence s) { return s == null || s.length() == 0; }

    // mirrors StoriesFragment.shouldFilterStory
    static boolean shouldFilterStory(Story story) {
        if (story == null) return false;
        if (filterWords != null && !isEmpty(story.title)) {
            String title = story.title.toLowerCase();
            for (String phrase : filterWords)
                if (!isEmpty(phrase) && title.contains(phrase.toLowerCase())) return true;
        }
        if (filterDomains != null && !isEmpty(story.url)) {
            String url = story.url.toLowerCase();
            for (String phrase : filterDomains)
                if (!isEmpty(phrase) && url.contains(phrase.toLowerCase())) return true;
        }
        return false;
    }

    public static void main(String[] a) {
        // "brain" set as a filter word, bloomberg.com as a filtered domain
        filterWords = Arrays.asList("brain", "crypto");
        filterDomains = Arrays.asList("bloomberg.com");

        List<Story> stories = new ArrayList<>();
        stories.add(new Story());                                                      // header placeholder (null title/url)
        stories.add(new Story("Your Brain Is Not a Computer", "https://nautil.us/x")); // should be filtered (case-insens)
        stories.add(new Story("brain-computer interfaces", "https://a.com/x"));        // should be filtered
        stories.add(new Story("Rust 1.80 released", "https://blog.rust-lang.org"));    // should stay
        stories.add(new Story("Markets update", "https://www.bloomberg.com/news"));    // filtered by domain
        stories.add(new Story("Ask HN: favourite editor?", null));                     // null url -> must not crash

        // mirrors the loadAlgolia loop
        Iterator<Story> it = stories.listIterator(1);
        while (it.hasNext()) {
            Story s = it.next();
            if (shouldFilterStory(s)) it.remove();
        }

        System.out.println("header preserved: " + (stories.get(0).title == null));
        System.out.println("remaining (" + (stories.size() - 1) + "):");
        for (int i = 1; i < stories.size(); i++) System.out.println("  - " + stories.get(i).title);

        boolean ok = stories.size() == 3
                && stories.get(1).title.equals("Rust 1.80 released")
                && stories.get(2).title.startsWith("Ask HN");
        System.out.println(ok ? "PASS" : "FAIL");
    }
}
